package vn.gasstation.integration.seenpro.provider;
import java.time.LocalDate;import java.util.Map;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.stereotype.Component;import vn.gasstation.integration.seenpro.client.SeenProHttpClient;import vn.gasstation.integration.seenpro.mapper.SeenProRevenueReportMapper;import vn.gasstation.integration.seenpro.parser.SeenProRevenueReportHtmlParser;import vn.gasstation.report.application.RevenueReportProvider;import vn.gasstation.report.domain.RevenueReport;
@Component @ConditionalOnProperty(name="app.data-source",havingValue="seenpro",matchIfMissing=true) public class SeenProRevenueReportAdapter implements RevenueReportProvider {private final SeenProHttpClient client;private final SeenProRevenueReportHtmlParser parser;private final SeenProRevenueReportMapper mapper;public SeenProRevenueReportAdapter(SeenProHttpClient client,SeenProRevenueReportHtmlParser parser,SeenProRevenueReportMapper mapper){this.client=client;this.parser=parser;this.mapper=mapper;}public RevenueReport get(LocalDate from,LocalDate to){var query=Map.of("t1",from.toString(),"g1","","t2",to.toString(),"g2","");return mapper.map(parser.parse(client.get("baocao.php",query)),from,to);}}
